		__SetCSSId([page], 0);
		pageId = __GetElementUniqueID(page);
		var n0 = __CreateView(pageId);
		__SetClasses(n0, "page");
		var n1 = __CreateText(pageId);
		__SetClasses(n1, "title");
		__AppendElement(n0, n1);
		var n2 = __CreateRawText("Octane UI Benchmark on Lynx · ready");
