		var n4 = __CreateView(pageId);
		__SetClasses(n4, "btn");
		__AddEvent(n4, 'bindEvent', "tap", "b:0");
		__AppendElement(n3, n4);
		var n5 = __CreateText(pageId);
		__SetClasses(n5, "btn-text");
		__AppendElement(n4, n5);
		var n6 = __CreateRawText("Create 1,000 rows");
		__AppendElement(n5, n6);
		var n7 = __CreateView(pageId);
		__SetClasses(n7, "btn");
		__AddEvent(n7, 'bindEvent', "tap", "b:1");
		__AppendElement(n3, n7);
		var n8 = __CreateText(pageId);
		__SetClasses(n8, "btn-text");
		__AppendElement(n7, n8);
		var n9 = __CreateRawText("Create 3,000 rows");
		__AppendElement(n8, n9);
		var n10 = __CreateView(pageId);
		__SetClasses(n10, "btn");
		__AddEvent(n10, 'bindEvent', "tap", "b:2");
		__AppendElement(n3, n10);
		var n11 = __CreateText(pageId);
		__SetClasses(n11, "btn-text");
